#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<long long> a(n);
    for (long long& x : a) cin >> x;

    sort(a.begin(), a.end());

    long long T;
    cin >> T;

    auto check = [&](int k) {
        for (int i = 0; i + k <= n; ++i) {
            if (a[i + k - 1] - a[i] <= T) return true;
        }
        return false;
    };

    int l = 1, r = n;
    while (l < r) {
        int mid = l + (r - l + 1) / 2;
        if (check(mid))
            l = mid;
        else
            r = mid - 1;
    }

    cout << l << '\n';
    return 0;
}

